export type Network = "mainnet" | "testnet";

export interface NetworkConfig {
  network: Network;
  /** REST base for trading, account, auth and deposit endpoints. */
  api: string;
  /** REST base for public market data (`/price/v2/...`). */
  price: string;
  /** REST base for public platform stats (`/stat/v1/...`). */
  stat: string;
  /** Public market-data WebSocket. */
  wsPrice: string;
  /** Authenticated user WebSocket (API-wallet `session.logon`). */
  wsUser: string;
  /** Strike web app, used for deep links (withdrawals, account pages). */
  app: string;
  /** CIP-30 `getNetworkId()` value the wallet must report. */
  cardanoNetworkId: 0 | 1;
  /** Bech32 prefix for Cardano payment addresses. */
  cardanoAddressPrefix: "addr" | "addr_test";
}

