    stat: "https://api.strikefinance.org/stat",
    wsPrice: "wss://api.strikefinance.org/ws/price",
    wsUser: "wss://api.strikefinance.org/ws/user-api",
    app: "https://app.strikefinance.org",
    cardanoNetworkId: 1,
